// Merge and filter keywords (Network, Security, Linux, AI, Cloud, VPN, Telecom)
const items = $input.all();
const validKeywords = [
  'vpn', 'proxy', 'vless', 'reality', 'tls', 'bgp', 'dns', 'linux', 'kernel',
  'security', 'vulnerability', 'zero-day', 'ddos', 'firewall', 'dpi',
  'فیلتر', 'اینترنت', 'پروکسی', 'شبکه', 'امنیت', 'لینوکس', 'سرور', 'فیبر نوری', 'همراه اول', 'ایرانسل'
];

const seenTitles = new Set();
const results = [];

for (const item of items) {
  const json = item.json;
  const title = (json.title || '').trim();
  const rawContent = (json.contentSnippet || json.content || json.description || '').toLowerCase();
  const fullText = (title + ' ' + rawContent).toLowerCase();

  if (!title || seenTitles.has(title)) continue;

  const isRelevant = validKeywords.some(k => fullText.includes(k));
  if (isRelevant) {
    seenTitles.add(title);
    const isPersian = /[؀-ۿ]/.test(title);
    results.push({
      json: {
        rawTitle: title,
        rawLink: json.link || json.guid,
        rawContent: json.contentSnippet || json.content || json.summary || '',
        pubDate: json.pubDate || json.isoDate || new Date().toISOString(),
        sourceName: json.creator || json['dc:creator'] || (isPersian ? 'خبرگزاری فناوری' : 'International Tech Media'),
        isPersian: isPersian
      }
    });
  }
}

return results.slice(0, 5); // Process up to 5 highest priority news per batch

