// Parse AI response and build the final NewsArticle JSON structure
const item = $input.item.json;
let parsedData;

try {
  const contentStr = item.choices[0].message.content.trim();
  // Remove markdown backticks if returned
  const cleaned = contentStr.replace(/^```json/i, '').replace(/^```/i, '').replace(/```$/i, '').trim();
  parsedData = JSON.parse(cleaned);
} catch (e) {
  parsedData = {
    title: $node['Filter Niche & Deduplicate'].json.rawTitle,
    slug: 'tech-news-' + Date.now(),
    summary: $node['Filter Niche & Deduplicate'].json.rawContent.slice(0, 160),
    content: [$node['Filter Niche & Deduplicate'].json.rawContent],
    category: 'tech_world',
    categoryLabelFa: 'دنیای لینوکس و سیستم‌ها',
    tags: ['فناوری', 'شبکه', 'امنیت'],
    readTimeMinutes: 3,
    isBreaking: false
  };
}

return {
  json: {
    id: 'news-' + Date.now() + '-' + Math.floor(Math.random() * 1000),
    slug: parsedData.slug || ('news-' + Date.now()),
    title: parsedData.title,
    summary: parsedData.summary,
    content: parsedData.content || [],
    category: parsedData.category || 'tech_world',
    categoryLabelFa: parsedData.categoryLabelFa || 'فناوری و شبکه',
    sourceName: $node['Filter Niche & Deduplicate'].json.sourceName || 'International Tech',
    sourceUrl: $node['Filter Niche & Deduplicate'].json.rawLink,
    sourceType: 'international',
    author: 'هوش مصنوعی و تحریریه اتصال',
    publishedAt: $node['Filter Niche & Deduplicate'].json.pubDate,
    readTimeMinutes: parsedData.readTimeMinutes || 3,
    imageUrl: 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=800&q=80',
    tags: parsedData.tags || ['شبکه', 'فناوری'],
    isBreaking: !!parsedData.isBreaking,
    viewsCount: Math.floor(Math.random() * 200) + 150
  }
};

